<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">docker</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> exec</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> minio</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> stat</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -c</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &#39;%n dev=%D&#39;</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /data</span></span>
